return;
}
const remembered = sessionStorage.getItem("kc_current_user");
if (remembered) {
currentUser = remembered;
const saved = getUserData(remembered);
if (saved) { scheduleData.length = 0; saved.forEach(r => scheduleData.push(r)); }
}
updateAccountUI();
}
