currentUser = user;
const saved = getUserData(user);
if (saved) { scheduleData.length = 0; saved.forEach(r => scheduleData.push(r)); renderSchedule(); }
sessionStorage.setItem("kc_current_user", user);
closeAuth();
updateAccountUI();
showToast("登录成功，欢迎回来 " + user);
}
}
